import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append(' ');
        }
        StringTokenizer st = new StringTokenizer(sb.toString());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long[] a = new long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());
        for (int i = 0; i < n; i++) b[i] = Long.parseLong(st.nextToken());

        // Análise (banco = nasalidade anterior - resistência anterior):
        // Anexar j exige banco + a_j >= 0, e o banco cresce em (a_j - d_j), onde
        // d_j = 0 se zerada, senão b_j.
        // -> Sílabas do meio com a_j - d_j < 0 nunca valem a pena (removê-las só
        //    aumenta o banco e a pontuação), então todas as transições tornam-se
        //    automaticamente válidas (banco >= 0 >= -a_j) e a ordem é irrelevante.
        // Papéis possíveis:
        //   - última sílaba L: contribui a_L (seu b nunca é pago) = base_L + g_L
        //   - sílaba do meio zerada: contribui a_i = base_i + g_i
        //   - sílaba do meio paga: contribui a_i - b_i <= base_i
        // onde base_i = max(a_i - b_i, 0) e g_i = min(a_i, b_i).
        // Total de papéis "privilegiados" (L + zerados) <= K+1, então a resposta é:
        //   soma de base_i + soma dos (K+1) maiores g_i.
        long ans = 0;
        long[] m = new long[n];
        for (int i = 0; i < n; i++) {
            long d = a[i] - b[i];
            if (d > 0) ans += d;
            m[i] = Math.min(a[i], b[i]);
        }
        int take = Math.min(k + 1, n);
        Arrays.sort(m);
        for (int i = n - 1; i >= n - take; i--) ans += m[i];
        System.out.println(ans);
    }
}
